& \mathrm{M}(\mathrm{~s}) \rightarrow \mathrm{M}(\mathrm{~g}) \Delta \mathrm{H}_{\text {sub }}^{\circ}=100 \mathrm{~kJ} \mathrm{~mol}^{-1}
\end{aligned}\mathrm{M}(\mathrm{~g}) \rightarrow \mathrm{M}^{+}(\mathrm{g})+\mathrm{e}^{-}(\mathrm{g}) \Delta \mathrm{H}_{\mathrm{i}}=500 \mathrm{~kJ} \mathrm{~mol}^{-1}\mathrm{X}(\mathrm{~g})+\mathrm{e}^{-}(\mathrm{g}) \rightarrow \mathrm{X}^{-}(\mathrm{g}) \Delta \mathrm{H}_{\mathrm{eg}}^*=-300 \mathrm{~kJ} \mathrm{~mol}^{-1}\mathrm{M}(\mathrm{~s})+\frac{1}{2} \mathrm{X}_2(\mathrm{~g}) \rightarrow \mathrm{M}^{+} \mathrm{X}^{-}(\mathrm{s}) \Delta \mathrm{H}_f^{\circ}=-400 \mathrm{~kJ} \mathrm{~mol}^{-1}$
